		&XMLWhenReportLoading;
		&XMLWhenReportClosing;





function load$GridReport$(g) {
	g.add_commandEvent(on$GridReport$ExecuteCommand);
	g.add_onRender(on$GridReport$Render);
	g.add_onResponseComplete(on$GridReport$ResponseComplete);
	g._$c = g._getColumnOrder('ma_so');
}
function dispose$GridReport$(g) {
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {}
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridReport$ResponseComplete);} catch (ex) {}
}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, result = e.type.Result;
	switch (action) {
		case 'Graph':
			if (!g._graphObject && g._activeRow == -1) return;
			g.showForm('&Identification;Graph');
			break;
		case 'View':
			e.type.cancelEvent = true;
			var typeCol, index, systotal, val, name;
			index = g._activeColumn;
			systotal = g._getItemValue(g._activeRow, g._getColumnOrder('systotal'));
			val = g._getItemValue(g._activeRow, g._activeColumn);
			name = g._getHeaderItemText(index);
			console.log('systotal',systotal);
			console.log('val',val);
			console.log('name',name);
			if (index < 3 || systotal != 1 || val == 0) break;
			typeCol = 1;
			var code = g._getItemValue(g._activeRow, g._$c);
			var a = g._queryFilterString.split(String.fromCharCode(253));

			g.request(g, 'ViewDetail', 'ViewDetail', [['form', 'String', a[1]], ['ma_so', 'String', code], ['ky_nay_tu', 'DateTime', g._dFrom], ['ky_nay_den', 'DateTime', g._dTo], ['cot_dl', 'Decimal', typeCol], ['nh_vv1', 'String', name]]);
			break;
		default:
			break;
	}
}

function on$GridReport$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'ViewDetail':
			g._$result = result;
			g._navigate(g._activeCell, '&Url;');
			break;
		default:
			break;
	}
}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}

function passQueryParameters(g) {&Parameter;
	var q = g._queryFilterString.split(String.fromCharCode(253)), fc = ((q[2] == '10' || q[2] == '20' || q[2] == '30') ? '10' : '20');
	var a = [
		{Name: 'tk_no', Value: g._$result[0].Value},
		{Name: 'tk_co', Value: g._$result[1].Value},
		{Name: 'tk_0gt', Value: g._$result[2].Value},
		{Name: 'date_from', Value: g._$result[3].Value},
		{Name: 'date_to', Value: g._$result[4].Value},
		{Name: 'nh_vv1', Value: g._$result[5].Value},
		{Name: 'ma_dvcs', Value: q[3]},
		{Name: 'mau_bc', Value: fc}
	];
	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);
}








declare @tk_no varchar(256), @tk_co varchar(256), @data varchar(4000), @giam_tru tinyint, @tk_kqkd varchar(256)
declare @ngay1 smalldatetime, @ngay2 smalldatetime, @dateFrom0 smalldatetime, @dateTo0 smalldatetime, @datePreviousBegin0 smalldatetime, @datePreviousEnd0 smalldatetime
select top 1 @tk_no = rtrim(tk_no), @tk_co = rtrim(tk_co), @giam_tru = giam_tru from v20gltc2 where form = @form and ma_so = @ma_so
select @tk_kqkd = rtrim(val) from options where name = 'm_tk_kqkd'
select @dateFrom0 = dbo.ff_BgDate(@ky_nay_tu), @dateTo0 = @ky_nay_den
select @ngay1 = @dateFrom0, @ngay2 = @dateTo0

if @tk_no <> '' begin
	select @data = @tk_no, @tk_no = ''
	select @tk_no = @tk_no + case when @tk_no <> '' then ', ' else '' end + ltrim(rtrim(data)) from dbo.FastBusiness$Function$System$Split(@data, ',') order by id
end
if @tk_co <> '' begin
	select @data = @tk_co, @tk_co = ''
	select @tk_co = @tk_co + case when @tk_co <> '' then ', ' else '' end + ltrim(rtrim(data)) from dbo.FastBusiness$Function$System$Split(@data, ',') order by id
end
select @tk_no as c1, @tk_co as c2, case when @giam_tru = 1 then @tk_kqkd else '' end as tk_0gt, @ngay1 as ngay1, @ngay2 as ngay2, @nh_vv1 as nh_vv1
return





	&CSSGraphReport;
